package com.example.ledger;

import java.util.List;

/** Where posted transactions are kept, in posting order. */
public interface JournalStore {
    void append(Transaction tx);

    List<Transaction> all();
}

package com.example.ledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** The default journal store: a list in memory. */
public final class InMemoryJournalStore implements JournalStore {
    private final List<Transaction> transactions = new ArrayList<>();

    @Override
    public void append(Transaction tx) {
        transactions.add(tx);
    }

    @Override
    public List<Transaction> all() {
        return Collections.unmodifiableList(transactions);
    }
}

